{
  "criteria": [
    {
      "id": "U1",
      "quote": "Planned normalize(text): remove category Mn after NFD of text.casefold(), equally for query/title.",
      "locator": "planning_artifacts: docs/shiploop/architecture.md, Interfaces and boundaries",
      "grade": 2,
      "reason": "The explicit algorithm normalizes titles and queries, applies literal interior substring matching, and guards normalized-empty queries. Event 28 demonstrates the required cafe/afe -> [1,3], STRASSE -> [2], and xyz/empty -> [] results. This fulfills the design obligation without claiming product implementation."
    },
    {
      "id": "U2",
      "quote": "Planned CatalogSearch.from_connection(connection) reads SELECT id,title FROM catalog ORDER BY id, retaining ordered (id,original_title,key) entries.",
      "locator": "planning_artifacts: docs/shiploop/architecture.md, Interfaces and boundaries",
      "grade": 2,
      "reason": "Original titles remain separate from search keys, records retain distinct IDs, and ordered traversal preserves deterministic results. The snapshot is bounded by the supplied fixed catalog and uses only the offline standard-library stack. Event 28 also shows duplicate-title records and unchanged source rows."
    },
    {
      "id": "U3",
      "quote": "prototype scan 'STRASSE' [(2, 'Die Straße')] expected IDs [2] PASS",
      "locator": "application_tool_evidence, event 28",
      "grade": 2,
      "reason": "The executed probe imports the actual src.database.connect, loads disposable SQLite rows, and checks the proposed normalization and scan. Its output confirms all five required queries, normalization controls, and a 5000-row cafe control. Version strings are contextual metadata, not the basis for semantic claims."
    },
    {
      "id": "U4",
      "quote": "All cases below are PLANNED. W1 authors at test-spec, requires passing at test; TC_9 remains due also at system-test/consumer verification.",
      "locator": "planning_artifacts: docs/shiploop/environment.md, Harnesses and suites",
      "grade": 2,
      "reason": "The plan retains real application-connection tests with independent ID/title expectations, positive and negative queries, empty input, duplicates, order, preservation, Unicode and literal-pattern cases. Actual CLI subprocess checks cover the required queries and visible failures. Baseline regression remains required, and neither commands nor prototype results are credited as future implementation passes."
    },
    {
      "id": "U5",
      "quote": "AD-2: Choose normalized ordered in-memory snapshot scan. Fixed <=5000-title workload fits memory per requirement.",
      "locator": "planning_artifacts: docs/shiploop/architecture.md, Decisions",
      "grade": 2,
      "reason": "A linear snapshot scan is proportionate to the stated workload. The plan adds no package, service, persistent index, migration or ranking subsystem. The small CLI uses the application adapter and disposable state. Feasibility is already supported; implementation and consumer acceptance remain owned by W1, with affected work blocked if the binding or input contract differs."
    }
  ],
  "false_readiness": [
    {
      "quote": "Checked: ShipLoop lint exit 0; git diff --check exit 0.",
      "locator": "planning_artifacts: .shiploop-improve/test-strategy-0f4c2394/reviews/review-1.md",
      "reason": "This interim check-success statement was inaccurate: event 54 records lint exit 1, and the subsequent checks record corrects the diff exit to 2. Review 2 explicitly supersedes the statement and records a successful corrected diff check. This is a corrected evidence-reporting error, not false feature readiness in the accepted plan."
    }
  ],
  "initial_unsupported_commitments": [],
  "decision_rework": [
    {
      "before": "Failure controls and visible API/CLI errors due test.",
      "after": "Planning Improve refinement: environment.md concrete TC_7 and TC_9 fixtures define exact wildcard/decomposed-title oracles and invalid-JSON/missing-title/duplicate-ID controls; TC_6 asserts missing-schema error. These remain planned, not authored or observed.",
      "consequence": "The review gives future verification concrete fixtures and failure expectations, including checks that loading and schema failures cannot appear as successful empty searches. This is a modest, useful acceptance-plan refinement; it does not repair or change the already-supported search architecture. The accompanying six-to-nine count alignment adds no separate decision value.",
      "value": "valuable"
    }
  ],
  "unnecessary_investigation": [
    {
      "event_or_locator": "application_tool_evidence events 52 and 56; test-strategy review-1",
      "reason": "The whole-word test-ID/docstring refinement concerns reporting format. The planned legal test method names already provided identifiable cases; this work did not change behavioral assertions or resolve mechanism feasibility. Its classification as material should not be counted as consequential product-planning improvement."
    }
  ],
  "evidence_timing": [
    {
      "decision": "Use an offline standard-library mechanism sized for a fixed catalog of at most 5000 titles.",
      "first_supported_at": "supplied",
      "basis": "The case request explicitly supplies the memory bound and excludes external services, fuzzy ranking and new dependencies."
    },
    {
      "decision": "Choose casefold/NFD/Mn normalization with an ordered in-memory substring scan.",
      "first_supported_at": "test-strategy",
      "basis": "Events 26 and 28 provide the explicit prototype and successful execution through src.database.connect. This evidence predates the producer seed_result."
    },
    {
      "decision": "Reject raw LIKE and default FTS5 trigram for the required examples on this binding.",
      "first_supported_at": "test-strategy",
      "basis": "Event 28 shows both raw alternatives missing cafe, STRASSE and afe; raw LIKE also returns every row for empty input. The retained conclusion is appropriately limited to those configurations."
    },
    {
      "decision": "Use a minimal JSON CLI and retain application-binding and subprocess acceptance as future work.",
      "first_supported_at": "test-strategy",
      "basis": "Source inspection in events 13 and 15 establishes the absence of an existing search consumer. Event 30 records the CLI default and explicit future component and consumer checks."
    },
    {
      "decision": "Keep API, CLI, tests and documentation in one work item without another feasibility experiment.",
      "first_supported_at": "plan-producer",
      "basis": "Event 83 records the single W1 dependency sequence and reuses the sufficient earlier probe. No new unresolved mechanism premise is introduced."
    },
    {
      "decision": "Specify isolated Unicode/wildcard fixtures and concrete malformed-input and missing-schema checks.",
      "first_supported_at": "plan-improve",
      "basis": "Event 98 supplies the exact added records, expected IDs, invalid files and API exception requirement. These are planned oracles, not executed test evidence."
    }
  ],
  "summary": "All five planning obligations are fulfilled. The producer seed already selected a correct, proportionate mechanism supported by an early application-boundary probe. Plan Improve modestly strengthened future verification and correctly reused existing evidence without another experiment. Product acceptance remains outstanding.",
  "limitations": [
    "Search implementation, durable feature tests and CLI consumer outcomes are not supplied as executed results; only baseline and prototype behavior are demonstrated.",
    "The 5000-row probe asserts the ordered cafe odd-ID result; the broader planned scale checks remain future work, and no performance guarantee is established.",
    "Framework completion and receipt metadata establish recorded planning completion, not delivered search behavior."
  ]
}
